import React from "react";
import { motion } from "framer-motion";
import { partners } from "../../data/content";
import AnimatedSection from "../ui/AnimatedSection";

export default function Partners() {
  // Double the array for seamless loop
  const doubled = [...partners, ...partners];

  return (
    <section id="partners" className="bg-charcoal-900 section-pad overflow-hidden">
      <div className="max-w-7xl mx-auto px-6 lg:px-10 mb-14">
        <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6">
          <div>
            <AnimatedSection variant="fadeUp">
              <span className="eyebrow text-white/35 mb-4 block">Technology Partners</span>
            </AnimatedSection>
            <AnimatedSection variant="fadeUp" delay={0.1}>
              <h2 className="font-display text-[clamp(2.2rem,4vw,3.2rem)] text-white leading-[1.12]">
                Global Brands.{" "}
                <em className="text-blue-400 not-italic">Local Delivery.</em>
              </h2>
            </AnimatedSection>
          </div>
          <AnimatedSection variant="fadeUp" delay={0.2} className="max-w-sm">
            <p className="text-white/40 text-sm leading-relaxed">
              We distribute, install, and service equipment from the world's leading cold chain and pathology technology manufacturers — supported by local aftersales teams.
            </p>
          </AnimatedSection>
        </div>
      </div>

      {/* Marquee — row 1 (forward) */}
      <div className="relative mb-3">
        {/* Fade edges */}
        <div className="absolute left-0 top-0 bottom-0 w-24 bg-gradient-to-r from-charcoal-900 to-transparent z-10 pointer-events-none" />
        <div className="absolute right-0 top-0 bottom-0 w-24 bg-gradient-to-l from-charcoal-900 to-transparent z-10 pointer-events-none" />

        <motion.div
          className="flex gap-3"
          animate={{ x: ["0%", "-50%"] }}
          transition={{ duration: 28, repeat: Infinity, ease: "linear" }}
        >
          {doubled.map((p, i) => (
            <PartnerTile key={`${p.id}-${i}`} partner={p} />
          ))}
        </motion.div>
      </div>

      {/* Marquee — row 2 (reverse) */}
      <div className="relative">
        <div className="absolute left-0 top-0 bottom-0 w-24 bg-gradient-to-r from-charcoal-900 to-transparent z-10 pointer-events-none" />
        <div className="absolute right-0 top-0 bottom-0 w-24 bg-gradient-to-l from-charcoal-900 to-transparent z-10 pointer-events-none" />

        <motion.div
          className="flex gap-3"
          animate={{ x: ["-50%", "0%"] }}
          transition={{ duration: 32, repeat: Infinity, ease: "linear" }}
        >
          {doubled.map((p, i) => (
            <PartnerTile key={`rev-${p.id}-${i}`} partner={p} dim />
          ))}
        </motion.div>
      </div>

      {/* Bottom note */}
      <AnimatedSection variant="fadeUp" delay={0.3} className="max-w-7xl mx-auto px-6 lg:px-10 mt-14">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4 pt-10 border-t border-white/10">
          <p className="text-white/30 text-[12.5px]">
            Authorised distributor and service partner across Kenya and East Africa.
          </p>
          <motion.button
            whileHover={{ scale: 1.03 }}
            whileTap={{ scale: 0.97 }}
            onClick={() => document.getElementById("contact")?.scrollIntoView({ behavior: "smooth" })}
            className="text-blue-400 text-[13px] font-bold tracking-wide underline-link hover:text-blue-300 transition-colors"
          >
            Enquire about a specific brand →
          </motion.button>
        </div>
      </AnimatedSection>
    </section>
  );
}

function PartnerTile({ partner, dim = false }) {
  return (
    <motion.div
      whileHover={{ scale: 1.04 }}
      transition={{ duration: 0.2 }}
      className={`flex-shrink-0 
        bg-white/45 
        backdrop-blur-sm
        border border-white/20 
        rounded-xl 
        px-7 py-5 
        flex items-center justify-center 
        cursor-default 
        min-w-[220px] 
        h-[110px]
        hover:bg-white/25
        transition-all duration-300
        ${dim ? "opacity-70" : ""}
      `}
    >
      <img
        src={partner.logo}
        alt={partner.name}
        className="max-h-14 max-w-[160px] object-contain"
        loading="lazy"
      />
    </motion.div>
  );
}
